package com.security.chat.multiplatform.common.encryption

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

class RsaSqueezerTest {

    @Test
    fun `squeezing and expanding work correctly`() {
        val original =
            ""

        val squeezed = RsaSqueezer.squeeze(original)

        // Squeezed should be significantly shorter than original
        assertTrue(
            squeezed.length < original.length / 2,
            "Squeezed length (${squeezed.length}) should be much shorter than original (${original.length})",
        )

        val expanded = RsaSqueezer.expand(squeezed)
        assertEquals(original, expanded, "Expanded key should match original")
    }
}
